from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CHECKBOXES = ROOT / "Minify" / "ui" / "checkboxes.py"
TEST = ROOT / "tests" / "test_profile_security.py"

text = CHECKBOXES.read_text(encoding="utf-8")

anchor = '''PROFILE_FILE_NAME = "mod-profiles.json"\nPROFILE_EXPORT_FORMAT = "minify-mod-profiles"\nPROFILE_EXPORT_VERSION = 1\n'''
replacement = '''PROFILE_FILE_NAME = "mod-profiles.json"\nPROFILE_EXPORT_FORMAT = "minify-mod-profiles"\nPROFILE_EXPORT_VERSION = 1\nPROFILE_MAX_FILE_BYTES = 8 * 1024 * 1024\nPROFILE_MAX_COUNT = 256\nPROFILE_MAX_STATES_PER_PROFILE = 5000\nPROFILE_MAX_TOTAL_STATES = 20000\nPROFILE_MAX_NAME_CHARS = 128\nPROFILE_MAX_MOD_ID_CHARS = 512\nPROFILE_MAX_HINT_CHARS = 512\n'''
if anchor not in text:
    raise SystemExit("profile constants anchor not found")
text = text.replace(anchor, replacement, 1)

start = text.index("def _load_profiles():")
end = text.index("\n\ndef _write_profiles():", start)
new_block = '''def _normalize_profile_states(states):\n    if not isinstance(states, dict):\n        raise ValueError("Profile mod states must be a JSON object.")\n    if len(states) > PROFILE_MAX_STATES_PER_PROFILE:\n        raise ValueError("Profile contains too many mod states.")\n\n    normalized = {}\n    for mod, enabled in states.items():\n        if not isinstance(mod, str) or not mod or len(mod) > PROFILE_MAX_MOD_ID_CHARS:\n            raise ValueError("Profile contains an invalid mod identifier.")\n        if not isinstance(enabled, bool):\n            raise ValueError("Profile mod states must use JSON booleans.")\n        normalized[mod] = enabled\n    return normalized\n\n\ndef _normalize_profiles_mapping(profiles):\n    if not isinstance(profiles, dict):\n        raise ValueError("Profiles must be a JSON object.")\n    if len(profiles) > PROFILE_MAX_COUNT:\n        raise ValueError("Profile bundle contains too many profiles.")\n\n    normalized = {}\n    total_states = 0\n    for name, value in profiles.items():\n        if not isinstance(name, str):\n            raise ValueError("Profile names must be strings.")\n        name = name.strip()\n        if not name or len(name) > PROFILE_MAX_NAME_CHARS or not isinstance(value, dict):\n            raise ValueError("Profile contains an invalid name or value.")\n        states = value.get("mods", value)\n        normalized_states = _normalize_profile_states(states)\n        total_states += len(normalized_states)\n        if total_states > PROFILE_MAX_TOTAL_STATES:\n            raise ValueError("Profile bundle contains too many total mod states.")\n        normalized[name] = normalized_states\n    return normalized\n\n\ndef _normalize_profile_hints(hints, referenced):\n    if hints in (None, {}):\n        return {}\n    if not isinstance(hints, dict) or len(hints) > PROFILE_MAX_TOTAL_STATES:\n        raise ValueError("Profile mod hints are invalid or excessive.")\n\n    normalized = {}\n    for mod, hint in hints.items():\n        if mod not in referenced:\n            continue\n        if not isinstance(mod, str) or len(mod) > PROFILE_MAX_MOD_ID_CHARS or not isinstance(hint, dict):\n            raise ValueError("Profile contains an invalid mod hint.")\n        clean = {}\n        for key in ("display_name", "source", "stable_key"):\n            value = hint.get(key, "")\n            if value is None:\n                value = ""\n            if not isinstance(value, str) or len(value) > PROFILE_MAX_HINT_CHARS:\n                raise ValueError("Profile contains an invalid mod hint value.")\n            clean[key] = value\n        normalized[mod] = clean\n    return normalized\n\n\ndef _load_profiles():\n    global profile_cache\n    try:\n        path = _profile_path()\n        if os.path.islink(path) or not os.path.isfile(path):\n            raise FileNotFoundError(path)\n        if os.path.getsize(path) > PROFILE_MAX_FILE_BYTES:\n            raise ValueError("Saved profile file exceeds the safety limit.")\n        with open(path, encoding="utf-8-sig") as file:\n            data = json.load(file)\n        profiles = data.get("profiles", data) if isinstance(data, dict) else {}\n        profile_cache = _normalize_profiles_mapping(profiles)\n    except Exception:\n        profile_cache = {}\n    return profile_cache\n'''
text = text[:start] + new_block + text[end:]

start = text.index("def _normalized_import_profiles(data):")
end = text.index("\n\ndef _current_profile_identity_indexes", start)
new_import = '''def _normalized_import_profiles(data):\n    try:\n        if not isinstance(data, dict):\n            raise ValueError("Profile bundle must be a JSON object.")\n        if "format" in data:\n            if data.get("format") != PROFILE_EXPORT_FORMAT or data.get("version") != PROFILE_EXPORT_VERSION:\n                raise ValueError("Unsupported Minify profile export format/version.")\n        profiles = data.get("profiles", data)\n        normalized = _normalize_profiles_mapping(profiles)\n        referenced = {mod for states in normalized.values() for mod in states}\n        hints = _normalize_profile_hints(data.get("mod_hints", {}), referenced)\n        return normalized, hints\n    except ValueError:\n        return {}, {}\n'''
text = text[:start] + new_import + text[end:]

old = '''    try:\n        with open(path, encoding="utf-8-sig") as file:\n            data = json.load(file)\n        imported, hints = _normalized_import_profiles(data)\n'''
new = '''    try:\n        if not os.path.isfile(path):\n            raise ValueError("Selected profile import is not a regular file.")\n        if os.path.getsize(path) > PROFILE_MAX_FILE_BYTES:\n            raise ValueError("Selected profile import exceeds the safety limit.")\n        with open(path, encoding="utf-8-sig") as file:\n            data = json.load(file)\n        imported, hints = _normalized_import_profiles(data)\n'''
if old not in text:
    raise SystemExit("import callback anchor not found")
text = text.replace(old, new, 1)

old = '''    if not name:\n        output.add_text("Enter a profile name before saving.", msg_type="warning")\n        return\n    profile_cache[name] = _current_states()\n'''
new = '''    if not name:\n        output.add_text("Enter a profile name before saving.", msg_type="warning")\n        return\n    if len(name) > PROFILE_MAX_NAME_CHARS:\n        output.add_text(f"Profile names are limited to {PROFILE_MAX_NAME_CHARS} characters.", msg_type="warning")\n        return\n    profile_cache[name] = _current_states()\n'''
if old not in text:
    raise SystemExit("save profile anchor not found")
text = text.replace(old, new, 1)

CHECKBOXES.write_text(text, encoding="utf-8")

TEST.write_text('''import json\nimport os\nimport sys\n\nsys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), "../Minify")))\n\nfrom ui import checkboxes\n\n\ndef test_profile_import_requires_strict_json_booleans():\n    profiles, hints = checkboxes._normalized_import_profiles(\n        {"profiles": {"Unsafe": {"mods": {"mod-a": "false"}}}}\n    )\n    assert profiles == {}\n    assert hints == {}\n\n\ndef test_profile_import_accepts_boolean_states_and_legacy_shape():\n    profiles, hints = checkboxes._normalized_import_profiles(\n        {"Legacy": {"mods": {"mod-a": True, "mod-b": False}}}\n    )\n    assert profiles == {"Legacy": {"mod-a": True, "mod-b": False}}\n    assert hints == {}\n\n\ndef test_profile_export_format_version_must_match():\n    profiles, _ = checkboxes._normalized_import_profiles(\n        {\n            "format": checkboxes.PROFILE_EXPORT_FORMAT,\n            "version": checkboxes.PROFILE_EXPORT_VERSION + 1,\n            "profiles": {"P": {"mods": {"m": True}}},\n        }\n    )\n    assert profiles == {}\n\n\ndef test_profile_bundle_rejects_excessive_profile_count(monkeypatch):\n    monkeypatch.setattr(checkboxes, "PROFILE_MAX_COUNT", 2)\n    payload = {"profiles": {f"P{i}": {"mods": {}} for i in range(3)}}\n    profiles, _ = checkboxes._normalized_import_profiles(payload)\n    assert profiles == {}\n\n\ndef test_profile_bundle_rejects_excessive_state_count(monkeypatch):\n    monkeypatch.setattr(checkboxes, "PROFILE_MAX_STATES_PER_PROFILE", 2)\n    payload = {"profiles": {"P": {"mods": {"a": True, "b": False, "c": True}}}}\n    profiles, _ = checkboxes._normalized_import_profiles(payload)\n    assert profiles == {}\n\n\ndef test_load_profiles_rejects_oversized_file(monkeypatch, tmp_path):\n    monkeypatch.setattr(checkboxes.base, "config_dir", str(tmp_path))\n    monkeypatch.setattr(checkboxes, "PROFILE_MAX_FILE_BYTES", 32)\n    path = tmp_path / checkboxes.PROFILE_FILE_NAME\n    path.write_text(json.dumps({"profiles": {"P": {"mods": {"a": True}}}}) + " " * 64)\n\n    assert checkboxes._load_profiles() == {}\n\n\ndef test_profile_hints_are_bounded_and_only_keep_referenced_mods():\n    payload = {\n        "format": checkboxes.PROFILE_EXPORT_FORMAT,\n        "version": checkboxes.PROFILE_EXPORT_VERSION,\n        "profiles": {"P": {"mods": {"a": True}}},\n        "mod_hints": {\n            "a": {"display_name": "A", "source": "Local", "stable_key": "mod:a"},\n            "unused": {"display_name": "Unused", "source": "", "stable_key": ""},\n        },\n    }\n    profiles, hints = checkboxes._normalized_import_profiles(payload)\n    assert profiles == {"P": {"a": True}}\n    assert hints == {"a": {"display_name": "A", "source": "Local", "stable_key": "mod:a"}}\n''', encoding="utf-8")
